<script>
  import SeoHead from '$lib/SeoHead.svelte';
  import { onMount } from 'svelte';
  import { projects, projectLevels, projectTechnologies } from '$lib/data/projects.js';
  import { allLessons } from '$lib/data/lessons/course-index.js';
  import { getProjectProgressSummary, PROGRESS_EVENT, readProgress } from '$lib/services/progress.js';

  let { data } = $props();
  let technology = $state('Tous');
  let level = $state('Tous');
  let summary = $state(null);
  let resumeHref = $state('/cours');
  const filteredProjects = $derived(data.projects.filter((project) =>
    (technology === 'Tous' || project.technologies.includes(technology)) &&
    (level === 'Tous' || project.level === level)
  ));

  onMount(() => {
    const refresh = () => {
      const progress = readProgress();
      summary = getProjectProgressSummary(progress);
      const last = allLessons.find((lesson) => lesson.id === progress.lastLessonId)
        ?? allLessons.map((lesson) => ({ lesson, visited: progress.lessons[lesson.id]?.lastVisitedAt })).filter((item) => item.visited).sort((a, b) => b.visited.localeCompare(a.visited))[0]?.lesson;
      if (last) resumeHref = last.type === 'legacy-lesson'
        ? `/apprendre?cours=${last.legacyCourseId}&lecon=${encodeURIComponent(last.title)}`
        : `/cours/${last.courseId}/lecons/${last.slug}`;
    };
    refresh();
    window.addEventListener(PROGRESS_EVENT, refresh);
    window.addEventListener('storage', refresh);
    return () => { window.removeEventListener(PROGRESS_EVENT, refresh); window.removeEventListener('storage', refresh); };
  });

  function stateFor(id) { return summary?.projects.find((entry) => entry.id === id); }
</script>

<SeoHead title="Projets pratiques HTML, CSS et JavaScript — WebSchool" description="Mets en pratique HTML, CSS et JavaScript avec des projets guidés et un suivi local de ta progression." path="/projets" />

<section class="projects-hero">
  <div class="hero-copy"><span class="eyebrow">APPRENDRE EN CONSTRUISANT</span><h1>Transforme tes connaissances en <em>vrais projets.</em></h1><p>Assemble les notions HTML, CSS et JavaScript pour créer des choses concrètes, à ton rythme et étape par étape.</p><div class="hero-actions"><a class="primary-button" href="#catalogue">Explorer les projets <span aria-hidden="true">→</span></a><a class="quiet-link" href={resumeHref}>Reprendre ma dernière leçon</a></div></div>
  <div class="code-visual" aria-label="Aperçu stylisé de code"><div class="window-bar"><i></i><i></i><i></i><span>mon-projet</span></div><div class="code-lines"><span><b>01</b> <i>&lt;main&gt;</i></span><span><b>02</b> &nbsp; <i>&lt;h1&gt;</i>Mon idée<i>&lt;/h1&gt;</i></span><span><b>03</b> &nbsp; <u>Construisons-la.</u></span><span><b>04</b> <i>&lt;/main&gt;</i></span><span class="code-cursor">▍</span></div><div class="floating-chip">✦ Petit projet, grand progrès</div></div>
</section>

<section class="benefits" aria-label="Pourquoi apprendre par projet"><article><span>01</span><h2>Apprends en construisant</h2><p>Chaque notion prend du sens quand tu l’utilises dans une réalisation.</p></article><article><span>02</span><h2>Relie les technologies</h2><p>Découvre comment HTML, CSS et JavaScript travaillent ensemble.</p></article><article><span>03</span><h2>Fais grandir ton portfolio</h2><p>Garde une trace de tes projets et des compétences mobilisées.</p></article></section>

<section id="catalogue" class="catalogue">
  <div class="section-heading"><div><span class="eyebrow">TON PROCHAIN DÉFI</span><h2>Choisis ton prochain projet</h2><p>Des idées progressives pour mettre en pratique les cours.</p></div><span class="catalogue-count">{filteredProjects.length} projet{filteredProjects.length === 1 ? '' : 's'}</span></div>
  <div class="filters" aria-label="Filtres des projets"><div class="filter-group" aria-label="Filtrer par technologie">{#each ['Tous', ...projectTechnologies] as item}<button type="button" class:active={technology === item} aria-pressed={technology === item} onclick={() => technology = item}>{item}</button>{/each}</div><div class="filter-group level-filters" aria-label="Filtrer par niveau">{#each ['Tous', ...projectLevels] as item}<button type="button" class:active={level === item} aria-pressed={level === item} onclick={() => level = item}>{item}</button>{/each}</div></div>
  {#if filteredProjects.length}
    <div class="project-grid">{#each filteredProjects as project (project.id)}
      {@const progress = stateFor(project.id)}
      <article class="project-card" data-level={project.level}>
        <div class="project-art" data-project={project.id}><span class="art-symbol" aria-hidden="true">{project.symbol}</span><span class="art-caption">{project.technologies.join(' · ')}</span><span class="art-state">{project.status === 'available' ? 'Atelier disponible' : 'Projet à réaliser'}</span></div>
        <div class="project-body"><div class="card-meta"><span class="level-badge" data-level={project.level}>{project.level}</span><span>{project.duration}</span></div><h3>{project.title}</h3><p class="project-description">{project.description}</p><div class="tech-list">{#each project.technologies as tech}<span>{tech}</span>{/each}</div><p class="concepts"><strong>Tu vas pratiquer</strong>{project.concepts.join(' · ')}</p>
          {#if progress?.status === 'completed'}<p class="project-progress done">✓ Projet terminé</p>{:else if progress?.status === 'started'}<p class="project-progress">En cours · commencé {new Date(progress.startedAt).toLocaleDateString('fr-FR')}</p>{/if}
          {#if project.status === 'available'}<a class="card-link" href={`/projets/${project.id}`}>{progress?.status === 'started' ? 'Reprendre le projet' : 'Découvrir le projet'} <span aria-hidden="true">→</span></a>{:else}<a class="card-link muted-link" href={`/projets/${project.id}`}>Voir la fiche du projet <span aria-hidden="true">→</span></a><span class="coming-soon">Parcours à réaliser</span>{/if}
        </div>
      </article>
    {/each}</div>
  {:else}<div class="empty-state"><span aria-hidden="true">⌕</span><h3>Aucun projet pour ces filtres</h3><p>Essaie une autre technologie ou un autre niveau.</p><button type="button" onclick={() => { technology = 'Tous'; level = 'Tous'; }}>Effacer les filtres</button></div>{/if}
</section>

<aside class="course-note"><span aria-hidden="true">✦</span><div><h2>Un projet te semble difficile ?</h2><p>Tu peux revoir les notions associées avant de continuer. Les fiches de projet pointent vers les leçons disponibles.</p></div><a href="/cours">Revoir les cours →</a></aside>

